package com.shubham.salarytracker;
import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import org.json.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,manifest=Config.NONE)
public class SyncPolicyTest {
 JSONObject snapshot(String id,String parent)throws Exception{return new JSONObject().put("id",id).put("description",new JSONObject().put("salarySync",1).put("parents",parent.isEmpty()?new JSONArray():new JSONArray().put(parent)).toString());}
 JSONObject data(String note)throws Exception{return new JSONObject().put("version",6).put("records",new JSONArray().put(new JSONObject().put("id","r").put("note",note)));}
 @Test public void detectsBranchesAndNeverUsesLatestTimestamp()throws Exception{JSONArray files=new JSONArray().put(snapshot("a","")).put(snapshot("b","a")).put(snapshot("c","a"));JSONArray heads=SyncPolicy.heads(files);assertEquals(2,heads.length());assertEquals("conflict",SyncPolicy.decide("local","base","a",heads,false));assertEquals("pull",SyncPolicy.decide("same","same","a",new JSONArray().put(snapshot("b","a")),false));assertEquals("merge",SyncPolicy.decide("changed","base","a",new JSONArray().put(snapshot("b","a")),false));assertEquals("upload",SyncPolicy.decide("changed","base","a",new JSONArray().put(snapshot("a","")),false));}
 @Test public void mergesIndependentChangesAndPreservesDeletions()throws Exception{JSONObject base=data("base"),local=data("changed"),remote=data("base");remote.getJSONArray("records").put(new JSONObject().put("id","new").put("note","remote"));JSONObject merged=SyncPolicy.merge(base,local,remote);assertEquals(2,merged.getJSONArray("records").length());assertEquals("changed",merged.getJSONArray("records").getJSONObject(0).getString("note"));local.put("records",new JSONArray());merged=SyncPolicy.merge(base,local,remote);assertEquals(1,merged.getJSONArray("records").length());assertEquals("new",merged.getJSONArray("records").getJSONObject(0).getString("id"));}
 @Test public void overlappingEditsAndDeleteVersusEditRequireReview()throws Exception{try{SyncPolicy.merge(data("base"),data("left"),data("right"));fail();}catch(IllegalStateException expected){}JSONObject local=data("base").put("records",new JSONArray());try{SyncPolicy.merge(data("base"),local,data("right"));fail();}catch(IllegalStateException expected){}}
 @Test public void canonicalHashIgnoresObjectKeyOrder()throws Exception{assertEquals(SyncPolicy.digest("{\"a\":1,\"b\":2}"),SyncPolicy.digest("{\"b\":2,\"a\":1}"));}
 @Test public void paymentParserRejectsSecretsFailuresAndAmbiguity()throws Exception{assertNull(PaymentDrafts.parse("OTP 123456 for payment Rs 100 successful",1));assertNull(PaymentDrafts.parse("Payment Rs 100 failed",1));assertNull(PaymentDrafts.parse("Request received for Rs 100",1));JSONObject p=PaymentDrafts.parse("Paid ₹1,250.50 UPI Ref 123456789012",1);assertEquals(125050,p.getLong("amount"));assertEquals("123456789012",p.getString("reference"));assertTrue(PaymentDrafts.parse("Received Rs 100 successfully",1).getBoolean("income"));assertTrue(PaymentDrafts.parse("Paid Rs 100. Balance Rs 500",1).isNull("amount"));assertEquals("card payment",PaymentDrafts.parse("Credit card bill payment Rs 100 successful",1).getString("special"));}
}
